import org.eclipse.swt.SWT;
import org.eclipse.swt.layout.GridData;
import org.eclipse.swt.widgets.Button;
import org.eclipse.swt.widgets.Composite;

public class GridDataNegativeExample {
    public void createButtons(Composite parent) {
        // Should not match: horizontal span is 2, not 1
        Button button1 = new Button(parent, SWT.PUSH);
        button1.setLayoutData(new GridData(SWT.FILL, SWT.FILL, true, false, 2, 1));

        // Should not match: uses a different constructor (4 args)
        Button button2 = new Button(parent, SWT.PUSH);
        button2.setLayoutData(new GridData(SWT.FILL, SWT.FILL, true, false));

        // Should not match: uses a different constructor (no args)
        Button button3 = new Button(parent, SWT.PUSH);
        button3.setLayoutData(new GridData());
    }
}
